        public static ReportingColumn FromString(string value)
        {
            if (value.Equals("SPEND_IN_MICRO_DOLLAR"))
                return ReportingColumn.SPENDINMICRODOLLAR;

            if (value.Equals("SPEND_IN_MICRO_US_DOLLAR"))
                return ReportingColumn.SPENDINMICROUSDOLLAR;

            if (value.Equals("BONUS_SPEND_IN_MICRO_DOLLAR"))
                return ReportingColumn.BONUSSPENDINMICRODOLLAR;

